<?php declare(strict_types=1);require __DIR__.'/app/core.php';if(!portal_installed()){header('Location: setup.php');exit;}start_portal_session();if(current_user()){header('Location: index.php');exit;}
$error='';if($_SERVER['REQUEST_METHOD']==='POST'){
 try{verify_csrf();if(login_is_blocked())throw new RuntimeException('Too many sign-in attempts. Try again in 15 minutes.');if((int)($_SESSION['login_tries']??0)>=12)throw new RuntimeException('Too many attempts in this browser session. Contact your administrator.');
 $u=strtolower(trim((string)($_POST['username']??'')));$pass=(string)($_POST['password']??'');$st=database()->prepare('SELECT id,password_hash,is_active FROM users WHERE username=?');$st->execute([$u]);$row=$st->fetch();
 if(!$row||!$row['is_active']||!password_verify($pass,$row['password_hash'])){$_SESSION['login_tries']=(int)($_SESSION['login_tries']??0)+1;record_login_failure();usleep(250000);throw new RuntimeException('Invalid username or password.');}
 $_SESSION['login_tries']=0;reset_login_failures();session_regenerate_id(true);$_SESSION['agent_id']=(int)$row['id'];header('Location: index.php');exit;
 }catch(Throwable $e){$error=$e->getMessage();}}
